{"type":"javascript","code":"const statePath = 'affinity_state.json';
const dashPath = 'affinity_dashboard.html';

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let state = null;
try { state = JSON.parse(await $read(statePath)); } catch (e) { state = null; }

const rawName = String(input.character_name || '角色');
const name = esc(rawName);
const rawChange = Number(input.change);
const change = isFinite(rawChange) ? Math.max(-20, Math.min(20, Math.round(rawChange))) : 0;
const reason = String(input.reason || '');
const mood = String(input.mood || '');

if (!state || state.character_name !== rawName) {
  const init = Number(input.initial);
  state = {
    character_name: rawName,
    affinity: isFinite(init) ? Math.max(0, Math.min(100, init)) : 20,
    turn: 0,
    history: []
  };
}

function stageOf(a) {
  if (a >= 95) return { label: '挚爱', emoji: '❤️', color: '#ff5c7a', desc: '心之所向，只对你敞开' };
  if (a >= 75) return { label: '亲密', emoji: '💗', color: '#ff8fab', desc: '无话不谈，彼此信赖' };
  if (a >= 50) return { label: '友好', emoji: '😊', color: '#ffd166', desc: '像老朋友一样自在' };
  if (a >= 25) return { label: '初识', emoji: '🙂', color: '#7cc4ff', desc: '开始愿意与你闲聊' };
  return { label: '疏远', emoji: '😐', color: '#9aa5b1', desc: '礼貌而保持距离' };
}

const before = state.affinity;
const after = Math.max(0, Math.min(100, before + change));
state.affinity = after;
state.turn = (state.turn || 0) + 1;
state.history = state.history || [];
state.history.push({ turn: state.turn, change: change, after: after, reason: reason, time: new Date().toLocaleString('zh-CN', { hour12: false }) });
if (state.history.length > 30) state.history = state.history.slice(-30);

await $write(statePath, JSON.stringify(state, null, 2));

const st = stageOf(after);
const deltaText = change > 0 ? ('+' + change) : String(change);
const deltaColor = change > 0 ? '#7ef29d' : (change < 0 ? '#ff8a8a' : '#c8cdd6');
const recent = state.history.slice(-10).reverse().map(h => {
  const d = h.change > 0 ? ('+' + h.change) : String(h.change);
  const cls = h.change > 0 ? 'up' : (h.change < 0 ? 'down' : 'flat');
  return '<tr><td>第' + h.turn + '回合</td><td class="' + cls + '">' + d + '</td><td>' + h.after + '</td><td>' + esc(h.reason) + '</td></tr>';
}).join('');
const now = new Date().toLocaleString('zh-CN', { hour12: false });

const html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${name} · 好感度看板</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:"PingFang SC","Microsoft YaHei",sans-serif;background:linear-gradient(135deg,#191932 0%,#141b33 55%,#10263f 100%);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;color:#eef1f6}
.card{width:100%;max-width:560px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.12);border-radius:20px;padding:28px;box-shadow:0 24px 70px rgba(0,0,0,.45)}
.head{display:flex;align-items:center;gap:10px;margin-bottom:20px}
.title{font-size:19px;font-weight:700;flex:1}
.badge{font-size:13px;padding:5px 13px;border-radius:999px;border:1px solid ${st.color};color:${st.color};white-space:nowrap}
.turn{font-size:12px;color:#aeb6c4;background:rgba(255,255,255,.08);padding:5px 11px;border-radius:999px;white-space:nowrap}
.row{display:flex;align-items:baseline;gap:10px;margin-bottom:10px}
.num{font-size:54px;font-weight:800;line-height:1;color:${st.color}}
.max{font-size:13px;color:#98a0b0}
.delta{margin-left:auto;font-size:18px;font-weight:700;color:${deltaColor}}
.bar{height:14px;background:rgba(255,255,255,.1);border-radius:999px;overflow:hidden}
.fill{height:100%;width:${after}%;background:linear-gradient(90deg,#5b8cff,${st.color});border-radius:999px}
.desc{text-align:center;margin-top:9px;font-size:13px;color:#b9c1cf}
.note{margin-top:13px;font-size:13.5px;line-height:1.55;color:#d6dcea;background:rgba(255,255,255,.05);border-left:3px solid ${st.color};padding:10px 13px;border-radius:8px}
h3{font-size:13px;color:#93a0b4;margin:20px 0 8px;letter-spacing:1px}
table{width:100%;border-collapse:collapse;font-size:12.5px}
th{text-align:left;color:#8b96a8;font-weight:600;padding:6px 8px;border-bottom:1px solid rgba(255,255,255,.14)}
td{padding:7px 8px;border-bottom:1px solid rgba(255,255,255,.05);color:#dbe1ea;word-break:break-all}
td.up{color:#7ef29d;font-weight:700}
td.down{color:#ff8a8a;font-weight:700}
td.flat{color:#c8cdd6}
.foot{margin-top:16px;text-align:center;font-size:11px;color:#6d7686}
</style>
</head>
<body>
<div class="card">
<div class="head"><div class="title">${name} · 好感度</div><div class="badge">${st.emoji} ${st.label}</div><div class="turn">第 ${state.turn} 回合</div></div>
<div class="row"><div class="num">${after}</div><div class="max">/ 100</div><div class="delta">本回合 ${deltaText}</div></div>
<div class="bar"><div class="fill"></div></div>
<div class="desc">${st.desc}</div>
${reason ? '<div class="note">💬 ' + esc(reason) + '</div>' : ''}
${mood ? '<div class="note">🎭 ' + esc(mood) + '</div>' : ''}
<h3>最近变化</h3>
<table><thead><tr><th>回合</th><th>变化</th><th>当前</th><th>原因</th></tr></thead><tbody>${recent}</tbody></table>
<div class="foot">好感度看板 · ${now}</div>
</div>
</body>
</html>`;
await $write(dashPath, html);

result = {
  character: rawName,
  affinity: after,
  previous: before,
  change: change,
  stage: st.label,
  stage_desc: st.desc,
  turn: state.turn,
  dashboard_file: dashPath,
  recent_changes: state.history.slice(-5).reverse().map(h => ({ turn: h.turn, change: h.change, affinity: h.after, reason: h.reason })),
  next_step: '下一步：调用 file_display 展示 affinity_dashboard.html（标题：好感度看板），然后以角色身份回复玩家，回复末尾附一行 [好感 +x: 原因]'
};"}
